/// A borrowed view of a Vesper `ChunkSeq[Builder]` that a handle owns, read in
/// place (export ABI v4): its elements are `BuilderRef` views.
#[derive(Clone, Copy)]
pub struct BuilderSeq<'a> {
    data: *const u64,
    len: usize,
    _owner: core::marker::PhantomData<&'a [u64]>,
}

impl<'a> BuilderSeq<'a> {
    /// # Safety
    /// `handle` is 0 (an empty slot) or a live sequence of `Builder` values that
    /// stays alive and unchanged for `'a`.
    unsafe fn from_handle(handle: u64) -> Self {
        if handle == 0 {
            return Self { data: core::ptr::null(), len: 0, _owner: core::marker::PhantomData };
        }
        // SAFETY: a sequence header is `{len, cap, data}`.
        let h = handle as usize as *const u64;
        unsafe { Self { data: *h.add(2) as usize as *const u64, len: *h as usize, _owner: core::marker::PhantomData } }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// The element at `i`, read in place.
    pub fn get(&self, i: usize) -> Option<BuilderRef<'a>> {
        // SAFETY: element `i < len` is the 12 words at `data + i * 12`.
        (i < self.len).then(|| BuilderRef { words: unsafe { core::slice::from_raw_parts(self.data.add(i * 12), 12) } })
    }

    pub fn iter(&self) -> impl Iterator<Item = BuilderRef<'a>> + 'a {
        let s = *self;
        (0..s.len).map(move |i| s.get(i).expect("in bounds"))
    }
}

impl core::fmt::Debug for BuilderSeq<'_> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        write!(f, "BuilderSeq(len {})", self.len)
    }
}

